    protected void Page_Load(object sender, EventArgs e)
    {
        try
        {
            isInternalCustomer = Converter.ToBool(Request.QueryString["isinternal"]) ? 1 : 0;
            rootUrl = Request.Url.GetLeftPart(UriPartial.Scheme) + Request.Headers["Host"] + Request.ApplicationPath + "/";

            WebUtils.SetNoCache();

            int reportNo = 1;
            reportNo = CastAide.AsInt32(Request.QueryString["repno"], 1);
            var tabId = CastAide.AsInt32(Request.QueryString["repno"], 1);
            isNewStatementTab = tabId == 1 ? 1 : 0;

            if (reportNo < 1 || reportNo > 5 || reportNo == 2)
            {
                //combine statement 1&2
                reportNo = 1;
            }

            if (tabId < 1 || tabId > 6 || tabId == 2)
            {
                tabId = 1;
            }

            //get datetime
            string fdate = WebUtils.GetQueryStringValue<string>("fdate", DateTime.Now.AddDays(-1).ToString("MM/dd/yyyy"));
            //CastAide.AsString(Request.QueryString["fdate"]);
            string tdate = WebUtils.GetQueryStringValue<string>("tdate", DateTime.Now.ToString("MM/dd/yyyy"));
            //  CastAide.AsString(Request.QueryString["tdate"]);

            DateTime fdt, tdt;

            if (!Validator.ValidDateMMDDYYYYNotNull(fdate, out fdt).IsSuccess())
                fdt = DateTime.Now;

            if (!Validator.ValidDateMMDDYYYYNotNull(tdate, out tdt).IsSuccess())
                tdt = DateTime.Now;

            //render banner search - filter
            reportHeader.Text = "Statement";
            RenderFilterBanner(tabId, reportNo, fdt, tdt);

            //for export to excel
            if (CastAide.AsInt32(Request.QueryString["IsExport"], 0) == 1)
            {
                string reportContent = string.Empty;
                string filenameSuffix = "-" + CastAide.AsString(AppSession.CustUName, string.Empty)
                                        + "-" + fdt.ToString("yyyyMMdd") + "-" + tdt.ToString("yyyyMMdd");

                switch (reportNo)
                {
                    case 1:
                        GenerateStatementExcelContent(fdate, tdate, filenameSuffix);
                        break;

                    case 3:
                        GenerateDetailExcelContent(fdate, tdate, filenameSuffix);
                        break;

                    case 4:
                        GenerateAuditExcelContent(filenameSuffix);
                        break;
                }
            }

        }
        catch (Exception ex)
        {
            Sunplus.Accounting.Core.Extensions.LogExtensions.ExceptionHandler(ex);
        }
    }

    private static void GenerateAuditExcelContent(string filenameSuffix)
    {
        filenameSuffix = "Audit" + filenameSuffix;

        string key = "accreportstatementaudit." + AppSession.AccUserName;
        var report = (IList<AuditStatement>)AppSession.GetSession(HttpContext.Current.Session, key);
        if (report != null)
        {
            string sheetname = filenameSuffix;
            string title = string.Format("Statement ({0}): {1} --> {1}", AppSession.CustUName, DateTime.Today.ToShortDateString());

            var excelExpoter = new AuditStatementExcel(report, sheetname);
            excelExpoter.ResponseStreamExcel(HttpContext.Current.Response, filenameSuffix, title);
        }
    }

    private static void GenerateDetailExcelContent(string fdate, string tdate, string filenameSuffix)
    {
        filenameSuffix = "Detail" + filenameSuffix;

        string key = "accreportstatementdetail." + AppSession.AccUserName;
        var report = (IList<DetailStatement>)AppSession.GetSession(HttpContext.Current.Session, key);
        if (report != null)
        {
            string sheetname = filenameSuffix;
            string title = string.Format("Statement ({0}): {1} --> {2}", AppSession.CustUName, fdate, tdate);

            var excelExpoter = new DetailStatementExcel(report, sheetname);
            excelExpoter.ResponseStreamExcel(HttpContext.Current.Response, filenameSuffix, title);
        }
    }

    private static void GenerateStatementExcelContent(string fromDate, string toDate, string filenameSuffix)
    {
        filenameSuffix = "Statement" + filenameSuffix;

        string key = "CustomerStatement" + AppSession.AccUserName;
        var report = (IList<OldStatement>)AppSession.GetSession(HttpContext.Current.Session, key);
        if (report != null)
        {
            string sheetname = filenameSuffix;
            string title = string.Format("Statement ({0}): {1} --> {2}", AppSession.CustUName, fromDate, toDate);
            
            var excelExpoter = new OldStatementExcel(report, sheetname);
            excelExpoter.ResponseStreamExcel(HttpContext.Current.Response, filenameSuffix, title);
        }
    }

